svg.script:
const GITHUB_USERNAME = "venusndk";

const API = "https://api.github.com";

/*
 * Languages we intentionally display.
 *
 * Add another language here if you want it permanently
 * represented in the visual.
 */
const LANGUAGE_CONFIG = {
  "Python": {
    bar: "Python-bar",
    percent: "Python-percent",
    color: "#3572A5"
  },

  "JavaScript": {
    bar: "JavaScript-bar",
    percent: "JavaScript-percent",
    color: "#f1e05a"
  },

  "Dart": {
    bar: "Dart-bar",
    percent: "Dart-percent",
    color: "#00B4AB"
  },

  "TypeScript": {
    bar: "TypeScript-bar",
    percent: "TypeScript-percent",
    color: "#3178c6"
  },

  "HTML": {
    bar: "HTML-bar",
    percent: "HTML-percent",
    color: "#e34c26"
  },

  "CSS": {
    bar: "CSS-bar",
    percent: "CSS-percent",
    color: "#663399"
  },

  "C#": {
    bar: "CSharp-bar",
    percent: "CSharp-percent",
    color: "#7355dd"
  },

  "SQL": {
    bar: "SQL-bar",
    percent: "SQL-percent",
    color: "#336791"
  }
};


/*
 * Fetch repositories.
 *
 * The GitHub API returns a maximum of 100 repositories
 * per request.
 */
async function getRepositories() {

  const repositories = [];

  let page = 1;

  while (true) {

    const response = await fetch(
      `${API}/users/${GITHUB_USERNAME}/repos?per_page=100&page=${page}&type=owner`
    );

    if (!response.ok) {
      throw new Error(
        `GitHub repositories request failed: ${response.status}`
      );
    }

    const data = await response.json();

    if (!Array.isArray(data) || data.length === 0) {
      break;
    }

    repositories.push(...data);

    if (data.length < 100) {
      break;
    }

    page++;
  }

  return repositories;
}


/*
 * Fetch language byte counts for one repository.
 */
async function getRepositoryLanguages(repository) {

  const response = await fetch(
    `${API}/repos/${GITHUB_USERNAME}/${repository.name}/languages`
  );

  if (!response.ok) {
    return {};
  }

  return await response.json();
}


/*
 * Combine language statistics across ALL repositories.
 */
async function calculateLanguages() {

  const repositories = await getRepositories();

  const totals = {};

  for (const repository of repositories) {

    /*
     * Skip forks.
     *
     * This prevents external projects forked by the user
     * from artificially increasing language percentages.
     */
    if (repository.fork) {
      continue;
    }

    const languages =
      await getRepositoryLanguages(repository);

    for (const [language, bytes] of Object.entries(languages)) {

      if (!totals[language]) {
        totals[language] = 0;
      }

      totals[language] += bytes;
    }
  }

  return totals;
}


/*
 * Convert raw bytes to percentages.
 */
function calculatePercentages(totals) {

  const totalBytes =
    Object.values(totals)
      .reduce((sum, value) => sum + value, 0);

  if (!totalBytes) {
    return {};
  }

  const percentages = {};

  for (const [language, bytes] of Object.entries(totals)) {

    percentages[language] =
      (bytes / totalBytes) * 100;
  }

  return percentages;
}


/*
 * Render language values into the SVG.
 */
function renderLanguages(percentages) {

  for (
    const [language, config]
    of Object.entries(LANGUAGE_CONFIG)
  ) {

    const percentage =
      percentages[language] || 0;

    const bar =
      document.getElementById(config.bar);

    const label =
      document.getElementById(config.percent);

    if (!bar || !label) {
      continue;
    }

    /*
     * Width is proportional to the percentage.
     *
     * Maximum width = 432px.
     */
    const width =
      Math.max(
        0,
        Math.min(432, (percentage / 100) * 432)
      );

    bar.setAttribute(
      "width",
      width.toFixed(2)
    );

    label.textContent =
      `${percentage.toFixed(2)}%`;

    bar.setAttribute(
      "fill",
      config.color
    );
  }
}


/*
 * Automatically discover languages that are NOT currently
 * represented in LANGUAGE_CONFIG.
 *
 * This lets you see what other technologies you have used.
 */
function discoverOtherLanguages(totals) {

  return Object.keys(totals)
    .filter(
      language =>
        !Object.prototype.hasOwnProperty.call(
          LANGUAGE_CONFIG,
          language
        )
    )
    .sort(
      (a, b) =>
        totals[b] - totals[a]
    );
}


/*
 * Start.
 */
async function updateTopLanguages() {

  try {

    const totals =
      await calculateLanguages();

    const percentages =
      calculatePercentages(totals);

    renderLanguages(percentages);

    /*
     * Expose discovered languages for debugging
     * or future UI expansion.
     */
    const otherLanguages =
      discoverOtherLanguages(totals);

    console.log(
      "All languages used by venusndk:",
      Object.keys(totals)
    );

    console.log(
      "Additional languages discovered:",
      otherLanguages
    );

  } catch (error) {

    console.error(
      "Unable to fetch GitHub language statistics:",
      error
    );

  }
}


updateTopLanguages();
